int file_fd; // File descriptor

// Acquire Advisory Shared Lock (Blocking)
int result_sh = flock(file_fd, LOCK_SH);

// Acquire Advisory Exclusive Lock (Non-Blocking)
int result_ex = flock(file_fd, LOCK_EX | LOCK_NB);

// Release (Unlock)
int result_un = flock(file_fd, LOCK_UN);

// Common Error: flock() locks are Advisory,
// not Mandatory. Other programs can ignore them.
